-- 0448 PROD CHECK, BEFORE the deploy (and after it): every hunk 0448 cuts occurs EXACTLY ONCE in the live body it cuts, nothing of 0448 is there
-- yet, and the self-assert probe's SELECTION (CLAUDE.md: a migration's selections run read-only on prod first). GENERATED by gen-checks.mjs.
--   npx --yes supabase@2.120.0 db query --linked --output-format json -f scripts/ops/harness/stats-one/hunks.sql
-- Run scripts/ops/harness/db-health/gate.sql first. ONE statement, read-only: the catalog (pg_get_functiondef of seven functions), and the probe's
-- selection: public.npc_fleets (~885 rows) with each one's fleet, route and ships by key, and the battles being fought. No function is called
-- but the catalog's.
-- BEFORE, wanted: ok true (every `n` 1); applied false; second_rule 3 (the three Stats bodies that each decide a state); probe.fleets 4 (four merchant fleets at sea or in port, with a route: the probe borrows
--   them inside a block it rolls back); newest_count not null (the row the file re-states once).
-- AFTER, wanted: applied true; every `n` 0 (no old text stands inside its new text); second_rule 0.
begin transaction read only;
with h (fn, ord, old) as (values
  ('public.stats_fleets_count(timestamp with time zone,timestamp with time zone)', 1, $h$  with
  nv as (select n.nation_id, n.fought_at, n.fought, f.status, s.ships,
$h$),
  ('public.stats_fleets_count(timestamp with time zone,timestamp with time zone)', 2, $h$    'merchants', jsonb_build_object('ships', (select count(*) from public.npc_fleets nf join public.ships x on x.fleet_id = nf.fleet_id)),
    'navy', (select jsonb_build_object('fleets', count(*), 'ships', coalesce(sum(nv.ships), 0),
                                       'sea', count(*) filter (where nv.state = 'sea'), 'port', count(*) filter (where nv.state = 'port'),
                                       'laid_up', count(*) filter (where nv.state = 'laid_up'), 'wrecked', count(*) filter (where nv.state = 'wrecked'),
                                       'nations', coalesce((select jsonb_agg(jsonb_build_array(z.code, z.fleets, z.ships) order by z.ships desc, z.code)
                                                              from (select na.code, count(*) as fleets, sum(y.ships) as ships
                                                                      from nv y join public.nations na on na.id = y.nation_id group by na.code) z), '[]'::jsonb))
               from nv),
    'pirates', (select jsonb_build_object('fleets', count(*), 'ships', coalesce(sum(pr.ships), 0),
                                          'sea', count(*) filter (where pr.state = 'sea'), 'port', count(*) filter (where pr.state = 'port'),
                                          'laid_up', count(*) filter (where pr.state = 'laid_up'), 'wrecked', count(*) filter (where pr.state = 'wrecked'),
                                          'wrecked_rows', count(*) filter (where pr.wrecked_at <= p_now),
                                          'roster', (select count(*) from public.pirate_roster),
                                          'homes', coalesce((select jsonb_agg(jsonb_build_array(z.code, z.name, z.fleets, z.ships) order by z.ships desc, z.code)
                                                               from (select po.code, po.name, count(*) as fleets, sum(y.ships) as ships
                                                                       from pr y join public.ports po on po.id = y.home_port group by po.code, po.name) z), '[]'::jsonb))
                  from pr),
    'cargo', (select jsonb_build_object('fleets', count(*), 'ships', coalesce(sum(cg.ships), 0),
                                        'sea', count(*) filter (where cg.state = 'sea'), 'port', count(*) filter (where cg.state = 'port'),
                                        'laid_up', count(*) filter (where cg.state = 'laid_up'), 'wrecked', count(*) filter (where cg.state = 'wrecked'),
                                        'tuns', round(coalesce(sum(cg.tuns), 0)), 'tuns_at_sea', round(coalesce(sum(cg.tuns) filter (where cg.state = 'sea'), 0)),
                                        'funds', public.funds_aboard())
                from cg),
$h$),
  ('public.stats_fleets_count(timestamp with time zone,timestamp with time zone)', 3, $h$  nv as (select n.nation_id, n.fought_at, n.fought, f.status, s.ships,
                case when n.laid_up_at is not null then 'laid_up' when not s.alive then 'wrecked' when f.status = 'SAILING' then 'sea' else 'port' end as state
$h$),
  ('public.stats_fleets_count(timestamp with time zone,timestamp with time zone)', 4, $h$  pr as (select n.home_port, n.wrecked_at, s.ships,
                case when n.laid_up_at is not null then 'laid_up' when n.wrecked_at is not null or not s.alive then 'wrecked' when f.status = 'SAILING' then 'sea' else 'port' end as state
$h$),
  ('public.stats_fleets_count(timestamp with time zone,timestamp with time zone)', 5, $h$                case when c.laid_up_at is not null then 'laid_up' when not s.alive then 'wrecked' when f.status = 'SAILING' then 'sea' else 'port' end as state
           from public.cargo_ships c
           join public.fleets f on f.id = c.fleet_id and c.laid_up_at is null   -- 0437: a retired (laid-up) cargo ship is out of the fleet's count
$h$),
  ('public.stats_fleet_list_rows(text,timestamp with time zone)', 1, $h$           case when f.laid is not null then 'laid_up' when f.wreck is not null or not x.alive then 'wrecked' when fl.status = 'SAILING' then 'sea' else 'port' end as state
      from f join public.fleets fl on fl.id = f.id
$h$),
  ('public.stats_fleet_list_rows(text,timestamp with time zone)', 2, $h$  select jsonb_build_object(
    'kind', p_kind,
    'fleets', (select count(*) from s), 'ships', (select coalesce(sum(s.ships), 0) from s),
    'sea', (select count(*) from s where s.state = 'sea'), 'port', (select count(*) from s where s.state = 'port'),
    'laid_up', (select count(*) from s where s.state = 'laid_up'), 'wrecked', (select count(*) from s where s.state = 'wrecked'),
$h$),
  ('public.tick_stats(timestamp with time zone)', 1, $h$  insert into public.stats_fleets (slot, at, figures)
  values (v_slot, p_now, public.stats_fleets_count(v_prev_at, p_now))
  on conflict (slot) do nothing;
  get diagnostics v_fl = row_count;
  delete from public.stats_fleets x where x.at < p_now - interval '26 hours';
  -- 0431: THE NAVY, PIRATES AND CARGO FACES (the owner, 2026-11-15: "a separate tab for navy, pirates, and cargoships like merchants"): one row a
  -- kind, replaced (public.stats_fleet_list_rows); and the fleets' book and lines kept 8 days.
  -- budget: 3 rows written a count; the book's hours older than 8 days deleted (about what one hour wrote 8 days ago: ~130-250 rows) and lines past 8 days (a few rows); ~45,000 small book rows read
  insert into public.stats_fleet_list (kind, at, figures)
  select k.kind, p_now, public.stats_fleet_list_rows(k.kind, p_now) from (values ('NAVY'), ('PIRATE'), ('CARGO')) k(kind)
  on conflict (kind) do update set at = excluded.at, figures = excluded.figures;
$h$),
  ('public.stats_merchant_fleets()', 1, $h$  select jsonb_build_object(
           'houses',    (select count(*) from public.npc_houses),
           'fleets',    (select count(*) from public.npc_fleets),
           'sailing',   count(*) filter (where f.status = 'SAILING'),
           'docked',    count(*) filter (where f.status in ('DOCKED', 'ANCHORED')),
           'repairing', count(*) filter (where f.status = 'REPAIRING'),
           'unable',    count(*) filter (where f.status in ('UNABLE_TO_SAIL', 'ADRIFT')),
           'laid_up',   (select count(*) from public.npc_fleets nf join public.standing_routes r on r.id = nf.route_id
                          where r.paused_reason = 'laid_up'))
    from public.npc_fleets nf join public.fleets f on f.id = nf.fleet_id
$h$),
  ('world.stats_fleets()', 1, $h$           'merchants', case when m.slot is null then null else jsonb_build_object(
                          'houses', m.houses, 'fleets', m.fleets, 'ships', (f.figures -> 'merchants' ->> 'ships')::int,
                          'sea', m.sailing, 'port', greatest(0, m.fleets - m.sailing - m.laid_up - m.unable), 'laid_up', m.laid_up, 'wrecked', m.unable,
                          'profit_day', m.profit_day, 'laps_day', m.laps_day) end,
$h$),
  ('world.stats_merchants(text)', 1, $h$  v_f := public.stats_merchant_fleets();
$h$),
  ('world.stats_merchants(text)', 2, $h$  return jsonb_build_object(
    'at', now(), 'counted_at', m.at, 'age_seconds', round(extract(epoch from now() - m.at)), 'slot_seconds', public.wc_num('drift_slot_seconds'), 'span', p_span,
    'houses', (v_f->>'houses')::int, 'fleets', (v_f->>'fleets')::int, 'sailing', (v_f->>'sailing')::int, 'docked', (v_f->>'docked')::int,
    'repairing', (v_f->>'repairing')::int, 'unable', (v_f->>'unable')::int, 'laid_up', (v_f->>'laid_up')::int, 'purse', v_p,
$h$),
  ('world.stats_merchants(text)', 3, $h$                                                      'sailing', (v_f->>'sailing')::int, 'laid_up', (v_f->>'laid_up')::int,
$h$),
  ('world.stats_fleet(uuid)', 1, $h$    'state', case when v_laid is not null then 'laid_up' when v_wreck is not null or not v_alive then 'wrecked' when f.status = 'SAILING' then 'sea' else 'port' end,
$h$)
), body as (
  select f.fn, replace(pg_get_functiondef(f.fn::regprocedure), E'\r', '') as def
    from (values ('public.stats_fleets_count(timestamp with time zone,timestamp with time zone)'), ('public.stats_fleet_list_rows(text,timestamp with time zone)'), ('public.tick_stats(timestamp with time zone)'), ('public.stats_merchant_fleets()'), ('world.stats_fleets()'), ('world.stats_merchants(text)'), ('world.stats_fleet(uuid)')) f(fn)
), n as (
  select h.fn, h.ord, (length(b.def) - length(replace(b.def, h.old, ''))) / length(h.old) as n from h join body b on b.fn = h.fn
), pick as (
  -- the probe's selection, by the facts the census will read (the census itself is not there before the deploy)
  select nf.fleet_id
    from public.npc_fleets nf join public.fleets f on f.id = nf.fleet_id
   where nf.route_id is not null and f.status in ('SAILING', 'DOCKED', 'ANCHORED', 'REPAIRING')
     and not exists (select 1 from public.standing_routes r where r.id = nf.route_id and r.paused_reason = 'laid_up')
     and exists (select 1 from public.ships s where s.fleet_id = nf.fleet_id and s.durability > 0)
     and nf.fleet_id not in (select bs.fleet_id from public.battles b join public.battle_sides bs on bs.battle_id = b.id where b.status = 'FIGHTING')
   order by nf.fleet_id limit 4
)
select jsonb_build_object(
  'at', now(),
  'head', (select max(m.version) from supabase_migrations.schema_migrations m),
  'ok', (select bool_and(n.n = 1) from n),
  'hunks', (select jsonb_agg(jsonb_build_object('fn', n.fn, 'ord', n.ord, 'n', n.n) order by n.fn, n.ord) from n),
  'bodies', (select jsonb_object_agg(b.fn, md5(b.def)) from body b),
  'applied', to_regprocedure('public.fleet_tally()') is not null,
  'second_rule', (select count(*) from pg_proc p join pg_namespace ns on ns.oid = p.pronamespace
                   where ns.nspname in ('public', 'cmd', 'world', 'voyage') and p.prokind in ('f', 'p') and p.proname <> 'fleet_state_of'
                     and (ns.nspname, p.proname) not in (('public', 'merchant_doing_at'), ('world', 'report'))
                     and p.prosrc ~ $re$then\s+'(sea|port|battle|laid_up|wrecked)'$re$),
  'probe', (select jsonb_build_object('fleets', count(*)) from pick),
  'newest_count', (select jsonb_build_object('slot', x.slot, 'at', x.at, 'lists', (select jsonb_object_agg(l.kind, l.at) from public.stats_fleet_list l))
                     from public.stats_fleets x order by x.slot desc limit 1)
) as r;
commit;
